using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using WpfTestIde.Execution;
using WpfTestIde.Models;

namespace WpfTestIde.Recording
{
    /// <summary>
    /// Turns a RecordedStep sequence into a Layer 1 Robot Framework test
    /// script — the C# equivalent of recorder/converter.py's
    /// generate_draft_test_script, kept line-for-line consistent with it
    /// so a script generated by this IDE is indistinguishable from one
    /// generated by the Python recorder pipeline.
    /// </summary>
    public static class ScriptGenerator
    {
        public static string Generate(
            IEnumerable<RecordedStep> nodes,
            string testCaseName = "Recorded Session Playback",
            string? driver = null,
            string? mode = null,
            List<string>? recordingModes = null,
            string? appId = null,
            IReadOnlyDictionary<string, List<string>>? datasets = null)
        {
            var nodeList = nodes.ToList();
            ScriptFlowValidator.Validate(nodeList, datasets);

            string shell = GenerateFlat(Array.Empty<RecordedStep>(), testCaseName, driver, mode, recordingModes, appId);
            const string testCasesHeader = "*** Test Cases ***";
            const string documentationLine = "    [Documentation]    Generated by WpfTestIde.";
            int testCasesIndex = shell.IndexOf(testCasesHeader, StringComparison.Ordinal);
            int documentationIndex = shell.IndexOf(documentationLine, StringComparison.Ordinal);
            if (testCasesIndex < 0 || documentationIndex < 0)
                throw new InvalidOperationException("Could not locate the generated Robot Framework test body.");

            var output = new StringBuilder();
            output.Append(shell, 0, testCasesIndex);
            AppendRobotDatasets(output, datasets);
            output.Append(shell, testCasesIndex, documentationIndex + documentationLine.Length - testCasesIndex);
            output.AppendLine();
            int conditionIndex = 0;
            int loopIndex = 0;
            AppendRobotNodes(output, nodeList, "    ", appId, datasets, ref conditionIndex, ref loopIndex);
            return output.ToString();
        }

        private static string GenerateFlat(
            IEnumerable<RecordedStep> steps,
            string testCaseName = "Recorded Session Playback",
            string? driver = null,
            string? mode = null,
            List<string>? recordingModes = null,
            string? appId = null)
        {
            var sb = new StringBuilder();
            sb.AppendLine("*** Settings ***");
            sb.AppendLine("Documentation    AUTO-GENERATED by WpfTestIde — raw Layer 3 calls.");
            sb.AppendLine("...              Functionally accurate but NOT YET production quality: consider");
            sb.AppendLine("...              refactoring repeated sequences into Layer 2 reusable modules");
            sb.AppendLine("...              before committing to the suite (see docs/RECORDER_GUIDE.md).");
            if (recordingModes != null && recordingModes.Count > 0)
            {
                sb.AppendLine("...              Recording modes: " + string.Join(", ", recordingModes));
            }
             sb.AppendLine("Library          ../TestAutoLayer/api/DriverAgnosticApi.py");

             // Combine mode and driver into a single Test Setup
             var setupParts = new List<string>();
             if (!string.IsNullOrEmpty(mode))
                 setupParts.Add(mode);
             if (!string.IsNullOrEmpty(driver))
                 setupParts.Add(driver);

             if (setupParts.Count == 2)
             {
                 sb.AppendLine($"Test Setup       Set Mode And Driver    {setupParts[0]}    {setupParts[1]}");
             }
             else if (setupParts.Count == 1)
             {
                 if (!string.IsNullOrEmpty(mode))
                     sb.AppendLine($"Test Setup       Set Mode    {mode}");
                 if (!string.IsNullOrEmpty(driver))
                     sb.AppendLine($"Test Setup       Set Driver    {driver}");
             }

             // Multi-app: register the attached app if app_id is known
             if (!string.IsNullOrEmpty(appId))
             {
                 sb.AppendLine($"Test Setup       Attach To Application    {appId}    %{{WPFSPY_PROCESS_ID}}    WPFSpy    %{{WPFSPY_PIPE_NAME}}");
             }

             sb.AppendLine();
            sb.AppendLine("*** Test Cases ***");
            sb.AppendLine(testCaseName);
            sb.AppendLine("    [Documentation]    Generated by WpfTestIde.");

            foreach (var step in steps)
            {
                string stepAppId = step.AppId ?? appId ?? "";
                string appIdArg = string.IsNullOrEmpty(stepAppId) ? "" : $"    app_id={stepAppId}";

                switch (step.Kind)
                {
                    case StepKind.Verify:
                        sb.AppendLine($"    Verify Element Text    {step.Alias}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.VerifyOcr:
                        sb.AppendLine($"    Get Data Grid Content Ocr    {step.Alias}{appIdArg}");
                        continue;
                    case StepKind.VerifyEnabled:
                        sb.AppendLine($"    Verify Element Enabled    {step.Alias}{appIdArg}");
                        continue;
                    case StepKind.VerifyVisible:
                        sb.AppendLine($"    Verify Element Visible    {step.Alias}{appIdArg}");
                        continue;
                    case StepKind.VerifyContains:
                        sb.AppendLine($"    Verify Element Contains Text    {step.Alias}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.VerifyRegex:
                        sb.AppendLine($"    Verify Element Text Matches Regex    {step.Alias}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.VerifyAttribute:
                        sb.AppendLine($"    Verify Element Attribute    {step.Alias}    {step.AttributeName}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.WaitExists:
                        sb.AppendLine($"    Wait Until Element Exists    {step.Alias}    timeout={step.Value}{appIdArg}");
                        continue;
                    case StepKind.WaitVisible:
                        sb.AppendLine($"    Wait Until Element Visible    {step.Alias}    timeout={step.Value}{appIdArg}");
                        continue;
                    case StepKind.WaitEnabled:
                        sb.AppendLine($"    Wait Until Element Enabled    {step.Alias}    timeout={step.Value}{appIdArg}");
                        continue;
                    case StepKind.WaitTextContains:
                        sb.AppendLine($"    Wait Until Element Text Contains    {step.Alias}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.CheckpointProperty:
                        sb.AppendLine($"    Property Checkpoint    {step.Alias}    {step.PropertyName}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.CheckpointArea:
                        sb.AppendLine($"    Area Checkpoint    {step.Alias}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.CheckpointImage:
                        sb.AppendLine($"    Image Checkpoint    {step.Alias}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.CheckpointDataGrid:
                        sb.AppendLine($"    Data Grid Checkpoint    {step.Alias}    {step.Value}{appIdArg}");
                        continue;
                    case StepKind.CheckpointCount:
                        sb.AppendLine($"    Count Checkpoint    {step.Alias}    {step.ExpectedCount}{appIdArg}");
                        continue;
                    case StepKind.CheckpointAttribute:
                        sb.AppendLine($"    Attribute Checkpoint    {step.Alias}    {step.AttributeName}    {step.Value}{appIdArg}");
                        continue;
                     case StepKind.LaunchApplication:
                     {
                         // Layout: Launch Application    <app_path>    [app_id=<id>]    [start_in=...]    [args=...]    [attach=Yes/No]    [timeout=...]    [drivers=...]    [spy_agent_enabled=Yes/No]    [pipe_name=...]
                         // The path is positional (must come first), then all named args.
                         // This avoids Robot Framework's "positional after named" error.
                         //
                         // Paths are emitted with forward slashes. Robot Framework strips
                         // backslashes from unquoted arguments (it interprets \W, \n, etc. as
                         // escape sequences), which silently corrupts Windows paths. Forward
                         // slashes are accepted by Popen + CreateProcess on Windows and
                         // avoid the issue entirely.
                         var la = new List<string> { "    Launch Application" };
                         la.Add(NormalizePathForRobot(step.AppPath));
                         if (!string.IsNullOrWhiteSpace(step.AppId ?? appId))
                             la.Add($"app_id={step.AppId ?? appId}");
                         if (!string.IsNullOrWhiteSpace(step.StartIn))
                             la.Add($"start_in={NormalizePathForRobot(step.StartIn)}");
                         if (!string.IsNullOrWhiteSpace(step.Args))
                             la.Add($"args={step.Args}");
                         if (!string.IsNullOrWhiteSpace(step.LaunchTimeout))
                             la.Add($"timeout={step.LaunchTimeout}");
                          la.Add($"attach={(step.AutoAttach ? "Yes" : "No")}");
                          // Emit driver priority list when available; fall back to single driver.
                          if (step.LaunchDriverList != null && step.LaunchDriverList.Any())
                          {
                              la.Add($"drivers={string.Join(",", step.LaunchDriverList)}");
                          }
                          else if (!string.IsNullOrWhiteSpace(step.LaunchDriver) && step.LaunchDriver != "WPFSpy")
                          {
                              la.Add($"driver={step.LaunchDriver}");
                          }
                           // Spy Agent options
                          if (!step.SpyAgentEnabled)
                              la.Add("spy_agent_enabled=No");
                          if (!string.IsNullOrWhiteSpace(step.PipeName))
                              la.Add($"pipe_name={step.PipeName}");
                          sb.AppendLine(string.Join("    ", la));
                         continue;
                     }
                    case StepKind.TerminateApplication:
                    {
                        // Layout: Terminate Application    [app_id=...]    [window_title=...]    [process_name=...]    [force=Yes/No]
                        var ta = new List<string> { "    Terminate Application" };
                        if (!string.IsNullOrWhiteSpace(step.AppId ?? appId))
                            ta.Add($"app_id={step.AppId ?? appId}");
                        if (!string.IsNullOrWhiteSpace(step.WindowTitle))
                            ta.Add($"window_title={step.WindowTitle}");
                        if (!string.IsNullOrWhiteSpace(step.ProcessName))
                            ta.Add($"process_name={step.ProcessName}");
                        if (step.ForceTerminate)
                            ta.Add("force=Yes");
                        sb.AppendLine(string.Join("    ", ta));
                        continue;
                    }
                }

                switch (step.Action)
                {
                    case ActionKind.Invoke:
                        sb.AppendLine($"    Click Element    {step.Alias}{appIdArg}");
                        break;
                    case ActionKind.SetValue:
                        sb.AppendLine($"    Set Element Value    {step.Alias}    {step.Value}{appIdArg}");
                        break;
                    case ActionKind.Toggle:
                        sb.AppendLine($"    Toggle Element    {step.Alias}{appIdArg}");
                        break;
                    case ActionKind.DoubleClick:
                        sb.AppendLine($"    Double Click Element    {step.Alias}{appIdArg}");
                        break;
                    case ActionKind.RightClick:
                        sb.AppendLine($"    Right Click Element    {step.Alias}{appIdArg}");
                        break;
                    case ActionKind.DragDrop:
                        sb.AppendLine($"    Drag And Drop    {step.Alias}    {step.TargetAlias}{appIdArg}");
                        break;
                    case ActionKind.Hover:
                        sb.AppendLine($"    Hover Over Element    {step.Alias}{appIdArg}");
                        break;
                    case ActionKind.PressKeys:
                        sb.AppendLine($"    Press Keys    {step.Alias}    {step.Value}{appIdArg}");
                        break;
                    case ActionKind.Scroll:
                        sb.AppendLine($"    Scroll    {step.Alias}    {step.Value}{appIdArg}");
                        break;
                    case ActionKind.SikuliClick:
                        sb.AppendLine($"    Sikuli Click    {step.Alias}    {step.Value}{appIdArg}");
                        break;
                    case ActionKind.SikuliType:
                        sb.AppendLine($"    Sikuli Type    {step.Alias}    {step.Value}{appIdArg}");
                        break;
                }
            }

            return sb.ToString();
        }

        private static void AppendRobotDatasets(StringBuilder output, IReadOnlyDictionary<string, List<string>>? datasets)
        {
            if (datasets == null || datasets.Count == 0)
                return;

            output.AppendLine("*** Variables ***");
            foreach (var dataset in datasets.OrderBy(pair => pair.Key, StringComparer.OrdinalIgnoreCase))
            {
                output.Append("@{__ide_dataset_").Append(dataset.Key).Append('}');
                foreach (var value in dataset.Value)
                    output.Append("    ").Append(value);
                output.AppendLine();
            }
            output.AppendLine();
        }

        private static void AppendRobotNodes(
            StringBuilder output,
            IEnumerable<RecordedStep> nodes,
            string indent,
            string? appId,
            IReadOnlyDictionary<string, List<string>>? datasets,
            ref int conditionIndex,
            ref int loopIndex)
        {
            foreach (var node in nodes)
            {
                switch (node.Kind)
                {
                    case StepKind.If:
                    {
                        int id = ++conditionIndex;
                        var condition = node.Condition!;
                        output.Append(indent).Append("${__ide_condition_").Append(id)
                            .Append("}=    Evaluate Script Condition    ")
                            .Append(condition.Kind).Append("    ").Append(condition.Alias);
                        if (condition.ExpectedValue != null)
                            output.Append("    expected_value=").Append(condition.ExpectedValue);
                        if (!string.IsNullOrWhiteSpace(condition.AppId ?? appId))
                            output.Append("    app_id=").Append(condition.AppId ?? appId);
                        output.AppendLine();
                        output.Append(indent).Append("IF    ${__ide_condition_").Append(id).AppendLine("}");
                        if (node.ThenSteps.Count == 0)
                            output.Append(indent).AppendLine("    No Operation");
                        else
                            AppendRobotNodes(output, node.ThenSteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        if (node.HasElse || node.ElseSteps.Count > 0)
                        {
                            output.Append(indent).AppendLine("ELSE");
                            if (node.ElseSteps.Count == 0)
                                output.Append(indent).AppendLine("    No Operation");
                            else
                                AppendRobotNodes(output, node.ElseSteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        }
                        output.Append(indent).AppendLine("END");
                        break;
                    }
                    case StepKind.Repeat:
                    {
                        int id = ++loopIndex;
                        output.Append(indent).Append("FOR    ${__ide_index_").Append(id)
                            .Append("}    IN RANGE    ").AppendLine(node.RepeatCount.ToString());
                        if (node.BodySteps.Count == 0)
                            output.Append(indent).AppendLine("    No Operation");
                        else
                            AppendRobotNodes(output, node.BodySteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        output.Append(indent).AppendLine("END");
                        break;
                    }
                    case StepKind.ForEach:
                    {
                        int id = ++loopIndex;
                        output.Append(indent).Append("FOR    ${").Append(node.LoopVariable).Append("}    IN");
                        if (node.LoopSourceKind == FlowLoopSourceKind.NamedDataset)
                        {
                            output.Append("    @{__ide_dataset_").Append(node.DatasetName).Append('}');
                        }
                        else
                        {
                            foreach (var value in node.LoopValues)
                                output.Append("    ").Append(value);
                            if (node.LoopValues.Count == 0)
                                output.Append("    @{EMPTY}");
                        }
                        output.AppendLine();
                        if (node.BodySteps.Count == 0)
                            output.Append(indent).AppendLine("    No Operation");
                        else
                            AppendRobotNodes(output, node.BodySteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        output.Append(indent).AppendLine("END");
                        break;
                    }
                    default:
                        AppendRobotAction(output, node, indent, appId);
                        break;
                }
            }
        }

        private static void AppendRobotAction(StringBuilder output, RecordedStep node, string indent, string? appId)
        {
            const string documentationLine = "    [Documentation]    Generated by WpfTestIde.";
            string generated = GenerateFlat(new[] { node }, "Generated Action", appId: appId);
            int bodyStart = generated.IndexOf(documentationLine, StringComparison.Ordinal);
            if (bodyStart < 0)
                return;
            bodyStart = generated.IndexOf('\n', bodyStart + documentationLine.Length);
            if (bodyStart < 0)
                return;

            foreach (var line in generated[(bodyStart + 1)..].Split('\n'))
            {
                string actionLine = line.TrimEnd('\r');
                if (actionLine.Length == 0)
                    continue;
                output.Append(indent);
                output.AppendLine(actionLine.StartsWith("    ", StringComparison.Ordinal) ? actionLine[4..] : actionLine);
            }
        }

        /// <summary>
        /// Turns a RecordedStep sequence into a Layer 1 Python test script
        /// that calls DriverAgnosticApi keywords directly. Mirrors Generate()
        /// so the same recorded steps can be emitted as either .robot or .py.
        /// </summary>
        public static string GeneratePython(
            IEnumerable<RecordedStep> nodes,
            string testCaseName = "test_recorded_session_playback",
            string? driver = null,
            string? mode = null,
            List<string>? recordingModes = null,
            string? appId = null,
            IReadOnlyDictionary<string, List<string>>? datasets = null)
        {
            var nodeList = nodes.ToList();
            ScriptFlowValidator.Validate(nodeList, datasets);

            string shell = GeneratePythonFlat(Array.Empty<RecordedStep>(), testCaseName, driver, mode, recordingModes, appId, datasets);
            const string docstring = "    \"\"\"Auto-generated from a recorded session.\"\"\"";
            const string footer = "if __name__ == '__main__':";
            int docIndex = shell.IndexOf(docstring, StringComparison.Ordinal);
            int footerIndex = shell.IndexOf(footer, StringComparison.Ordinal);
            if (docIndex < 0 || footerIndex < 0 || footerIndex < docIndex)
                throw new InvalidOperationException("Could not locate the generated Python test body.");

            int bodyStart = shell.IndexOf('\n', docIndex + docstring.Length);
            if (bodyStart < 0)
                throw new InvalidOperationException("Could not locate the generated Python body indentation.");
            var output = new StringBuilder(shell, 0, bodyStart + 1, shell.Length + 256);
            int conditionIndex = 0;
            int loopIndex = 0;
            AppendPythonNodes(output, nodeList, "    ", appId, datasets, ref conditionIndex, ref loopIndex);
            output.Append(shell, footerIndex, shell.Length - footerIndex);
            return output.ToString();
        }

        private static string GeneratePythonFlat(
            IEnumerable<RecordedStep> steps,
            string testCaseName = "test_recorded_session_playback",
            string? driver = null,
            string? mode = null,
            List<string>? recordingModes = null,
            string? appId = null,
            IReadOnlyDictionary<string, List<string>>? datasets = null)
        {
            string Quote(string? value) => System.Text.Json.JsonSerializer.Serialize(value ?? "");
            string PythonValue(string? value)
            {
                if (value != null && Regex.IsMatch(value, @"\$\{[A-Za-z_][A-Za-z0-9_]*\}", RegexOptions.CultureInvariant))
                    return "api.resolve_script_value(" + Quote(value) + ", locals())";
                return Quote(value);
            }
            var sb = new StringBuilder();
            sb.AppendLine("# AUTO-GENERATED by WpfTestIde — raw Layer 3 calls.");
            sb.AppendLine("# Functionally accurate but NOT YET production quality:");
            sb.AppendLine("# refactor repeated sequences into Layer 2 reusable modules");
            sb.AppendLine("# before committing to the suite (see docs/RECORDER_GUIDE.md).");
            if (recordingModes != null && recordingModes.Count > 0)
                sb.AppendLine("# Recording modes: " + string.Join(", ", recordingModes));
            sb.AppendLine("import os");
            sb.AppendLine("from TestAutoLayer.api.DriverAgnosticApi import DriverAgnosticApi");
            if (datasets != null && datasets.Count > 0)
                sb.AppendLine("__ide_datasets = " + System.Text.Json.JsonSerializer.Serialize(datasets));
            sb.AppendLine();
            sb.AppendLine("api = DriverAgnosticApi()");
            sb.AppendLine();

            if (!string.IsNullOrEmpty(mode) && !string.IsNullOrEmpty(driver))
                sb.AppendLine("api.set_mode_and_driver(" + Quote(mode) + ", " + Quote(driver) + ")");
            else if (!string.IsNullOrEmpty(mode))
                sb.AppendLine("api.set_mode(" + Quote(mode) + ")");
            else if (!string.IsNullOrEmpty(driver))
                sb.AppendLine("api.set_driver(" + Quote(driver) + ")");

            if (!string.IsNullOrEmpty(appId))
            {
                sb.AppendLine("api.attach_to_application(" + Quote(appId)
                    + ", os.environ.get('WPFSPY_PROCESS_ID', '0'), 'WPFSpy', os.environ.get('WPFSPY_PIPE_NAME'))");
            }

            sb.AppendLine();
            sb.AppendLine("def " + testCaseName + "():");
            sb.AppendLine("    \"\"\"Auto-generated from a recorded session.\"\"\"");

            foreach (var step in steps)
            {
                string stepAppId = step.AppId ?? appId ?? "";
                string appIdArg = string.IsNullOrEmpty(stepAppId) ? "" : ", app_id=" + Quote(stepAppId);
                string alias = PythonValue(step.Alias);
                string value = PythonValue(step.Value);

                switch (step.Kind)
                {
                    case StepKind.Verify:
                        sb.AppendLine("    api.verify_element_text(" + alias + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.VerifyOcr:
                        sb.AppendLine("    api.get_data_grid_content_ocr(" + alias + appIdArg + ")");
                        continue;
                    case StepKind.VerifyEnabled:
                        sb.AppendLine("    api.verify_element_enabled(" + alias + appIdArg + ")");
                        continue;
                    case StepKind.VerifyVisible:
                        sb.AppendLine("    api.verify_element_visible(" + alias + appIdArg + ")");
                        continue;
                    case StepKind.VerifyContains:
                        sb.AppendLine("    api.verify_element_contains_text(" + alias + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.VerifyRegex:
                        sb.AppendLine("    api.verify_element_text_matches_regex(" + alias + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.VerifyAttribute:
                        sb.AppendLine("    api.verify_element_attribute(" + alias + ", " + PythonValue(step.AttributeName) + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.WaitExists:
                        sb.AppendLine("    api.wait_until_element_exists(" + alias + ", timeout=" + (step.Value ?? "5") + appIdArg + ")");
                        continue;
                    case StepKind.WaitVisible:
                        sb.AppendLine("    api.wait_until_element_visible(" + alias + ", timeout=" + (step.Value ?? "5") + appIdArg + ")");
                        continue;
                    case StepKind.WaitEnabled:
                        sb.AppendLine("    api.wait_until_element_enabled(" + alias + ", timeout=" + (step.Value ?? "5") + appIdArg + ")");
                        continue;
                    case StepKind.WaitTextContains:
                        sb.AppendLine("    api.wait_until_element_text_contains(" + alias + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.CheckpointProperty:
                        sb.AppendLine("    api.property_checkpoint(" + alias + ", " + PythonValue(step.PropertyName) + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.CheckpointArea:
                        sb.AppendLine("    api.area_checkpoint(" + alias + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.CheckpointImage:
                        sb.AppendLine("    api.image_checkpoint(" + alias + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.CheckpointDataGrid:
                        sb.AppendLine("    api.data_grid_checkpoint(" + alias + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.CheckpointCount:
                        sb.AppendLine("    api.count_checkpoint(" + alias + ", " + PythonValue(step.ExpectedCount) + appIdArg + ")");
                        continue;
                    case StepKind.CheckpointAttribute:
                        sb.AppendLine("    api.attribute_checkpoint(" + alias + ", " + PythonValue(step.AttributeName) + ", " + value + appIdArg + ")");
                        continue;
                    case StepKind.LaunchApplication:
                    {
                        var launchArgs = new List<string> { PythonValue(NormalizePathForPython(step.AppPath)) };
                        if (!string.IsNullOrWhiteSpace(step.AppId ?? appId)) launchArgs.Add("app_id=" + Quote(step.AppId ?? appId));
                        if (!string.IsNullOrWhiteSpace(step.StartIn)) launchArgs.Add("start_in=" + PythonValue(NormalizePathForPython(step.StartIn)));
                        if (!string.IsNullOrWhiteSpace(step.Args)) launchArgs.Add("args=" + PythonValue(step.Args));
                        if (!string.IsNullOrWhiteSpace(step.LaunchTimeout)) launchArgs.Add("timeout=" + step.LaunchTimeout);
                        var drivers = step.LaunchDriverList?.Count > 0
                            ? step.LaunchDriverList
                            : new List<string> { step.LaunchDriver };
                        launchArgs.Add("drivers=[" + string.Join(", ", drivers.Select(Quote)) + "]");
                        launchArgs.Add("attach=" + (step.AutoAttach ? "True" : "False"));
                        launchArgs.Add("spy_agent_enabled=" + (step.SpyAgentEnabled ? "True" : "False"));
                        if (!string.IsNullOrWhiteSpace(step.PipeName)) launchArgs.Add("pipe_name=" + PythonValue(step.PipeName));
                        sb.AppendLine("    api.launch_application(" + string.Join(", ", launchArgs) + ")");
                        continue;
                    }
                    case StepKind.TerminateApplication:
                    {
                        var terminateArgs = new List<string>();
                        if (!string.IsNullOrWhiteSpace(step.AppId ?? appId)) terminateArgs.Add("app_id=" + Quote(step.AppId ?? appId));
                        if (!string.IsNullOrWhiteSpace(step.WindowTitle)) terminateArgs.Add("window_title=" + PythonValue(step.WindowTitle));
                        if (!string.IsNullOrWhiteSpace(step.ProcessName)) terminateArgs.Add("process_name=" + PythonValue(step.ProcessName));
                        if (step.ForceTerminate) terminateArgs.Add("force=True");
                        sb.AppendLine("    api.terminate_application(" + string.Join(", ", terminateArgs) + ")");
                        continue;
                    }
                }

                switch (step.Action)
                {
                    case ActionKind.Invoke: sb.AppendLine("    api.click_element(" + alias + appIdArg + ")"); break;
                    case ActionKind.SetValue: sb.AppendLine("    api.set_element_value(" + alias + ", " + value + appIdArg + ")"); break;
                    case ActionKind.Toggle: sb.AppendLine("    api.toggle_element(" + alias + appIdArg + ")"); break;
                    case ActionKind.DoubleClick: sb.AppendLine("    api.double_click_element(" + alias + appIdArg + ")"); break;
                    case ActionKind.RightClick: sb.AppendLine("    api.right_click_element(" + alias + appIdArg + ")"); break;
                    case ActionKind.DragDrop: sb.AppendLine("    api.drag_and_drop(" + alias + ", " + PythonValue(step.TargetAlias) + appIdArg + ")"); break;
                    case ActionKind.Hover: sb.AppendLine("    api.hover_over_element(" + alias + appIdArg + ")"); break;
                    case ActionKind.PressKeys: sb.AppendLine("    api.press_keys(" + alias + ", " + value + appIdArg + ")"); break;
                    case ActionKind.Scroll: sb.AppendLine("    api.scroll(" + alias + ", " + value + appIdArg + ")"); break;
                    case ActionKind.SikuliClick: sb.AppendLine("    api.sikuli_click(" + alias + ", " + value + appIdArg + ")"); break;
                    case ActionKind.SikuliType: sb.AppendLine("    api.sikuli_type(" + alias + ", " + value + appIdArg + ")"); break;
                }
            }

            sb.AppendLine();
            sb.AppendLine("if __name__ == '__main__':");
            sb.AppendLine("    " + testCaseName + "()");
            return sb.ToString();
        }

        private static void AppendPythonNodes(
            StringBuilder output,
            IEnumerable<RecordedStep> nodes,
            string indent,
            string? appId,
            IReadOnlyDictionary<string, List<string>>? datasets,
            ref int conditionIndex,
            ref int loopIndex)
        {
            foreach (var node in nodes)
            {
                switch (node.Kind)
                {
                    case StepKind.If:
                    {
                        int id = ++conditionIndex;
                        var condition = node.Condition!;
                        var args = new List<string>
                        {
                            PythonQuote(condition.Kind.ToString()),
                            "alias=" + PythonValueExpression(condition.Alias),
                        };
                        if (condition.ExpectedValue != null)
                            args.Add("expected_value=" + PythonValueExpression(condition.ExpectedValue));
                        if (!string.IsNullOrWhiteSpace(condition.AppId ?? appId))
                            args.Add("app_id=" + PythonQuote(condition.AppId ?? appId));
                        output.Append(indent).Append("if api.evaluate_script_condition(")
                            .Append(string.Join(", ", args)).AppendLine("):");
                        if (node.ThenSteps.Count == 0)
                            output.Append(indent).AppendLine("    pass");
                        else
                            AppendPythonNodes(output, node.ThenSteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        if (node.HasElse || node.ElseSteps.Count > 0)
                        {
                            output.Append(indent).AppendLine("else:");
                            if (node.ElseSteps.Count == 0)
                                output.Append(indent).AppendLine("    pass");
                            else
                                AppendPythonNodes(output, node.ElseSteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        }
                        break;
                    }
                    case StepKind.Repeat:
                    {
                        int id = ++loopIndex;
                        output.Append(indent).Append("for __ide_index_").Append(id)
                            .Append(" in range(").Append(node.RepeatCount).AppendLine("):");
                        if (node.BodySteps.Count == 0)
                            output.Append(indent).AppendLine("    pass");
                        else
                            AppendPythonNodes(output, node.BodySteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        break;
                    }
                    case StepKind.ForEach:
                    {
                        string source = node.LoopSourceKind == FlowLoopSourceKind.NamedDataset
                            ? "__ide_datasets[" + PythonQuote(datasets?.Keys.FirstOrDefault(name => string.Equals(name, node.DatasetName, StringComparison.OrdinalIgnoreCase)) ?? node.DatasetName) + "]"
                            : "[" + string.Join(", ", node.LoopValues.Select(PythonValueExpression)) + "]";
                        output.Append(indent).Append("for ").Append(node.LoopVariable).Append(" in ").Append(source).AppendLine(":");
                        if (node.BodySteps.Count == 0)
                            output.Append(indent).AppendLine("    pass");
                        else
                            AppendPythonNodes(output, node.BodySteps, indent + "    ", appId, datasets, ref conditionIndex, ref loopIndex);
                        break;
                    }
                    default:
                        AppendPythonAction(output, node, indent, appId);
                        break;
                }
            }
        }

        private static void AppendPythonAction(StringBuilder output, RecordedStep node, string indent, string? appId)
        {
            const string docstring = "    \"\"\"Auto-generated from a recorded session.\"\"\"";
            const string footer = "if __name__ == '__main__':";
            string generated = GeneratePythonFlat(new[] { node }, "generated_step", appId: appId);
            int docIndex = generated.IndexOf(docstring, StringComparison.Ordinal);
            int footerIndex = generated.IndexOf(footer, StringComparison.Ordinal);
            if (docIndex < 0 || footerIndex < 0)
                return;
            int bodyStart = generated.IndexOf('\n', docIndex + docstring.Length);
            if (bodyStart < 0 || bodyStart >= footerIndex)
                return;

            foreach (var line in generated[(bodyStart + 1)..footerIndex].Split('\n'))
            {
                string actionLine = line.TrimEnd('\r');
                if (actionLine.Length == 0)
                    continue;
                output.Append(indent);
                output.AppendLine(actionLine.StartsWith("    ", StringComparison.Ordinal) ? actionLine[4..] : actionLine);
            }
        }

        private static string PythonQuote(string? value)
            => System.Text.Json.JsonSerializer.Serialize(value ?? "");

        private static string PythonValueExpression(string? value)
        {
            string literal = PythonQuote(value);
            return value != null && Regex.IsMatch(value, @"\$\{[A-Za-z_][A-Za-z0-9_]*\}", RegexOptions.CultureInvariant)
                ? "api.resolve_script_value(" + literal + ", locals())"
                : literal;
        }

        /// <summary>
        /// Convert a Windows path (with backslashes) to a Python-safe
        /// form. Python interprets backslashes as escape sequences in
        /// string literals, so a path like "C:\Windows\notepad.exe"
        /// silently becomes "C:Windows\notepad.exe". Forward slashes
        /// are accepted by Popen + CreateProcess on Windows and avoid
        /// the issue entirely.
        /// </summary>
        public static string NormalizePathForPython(string? path)
        {
            if (string.IsNullOrEmpty(path)) return path ?? "";
            return path.Replace('\\', '/');
        }

        /// <summary>
        /// Convert a Windows path (with backslashes) to a Robot-Framework-safe
        /// form. Robot strips backslashes from unquoted arguments because it
        /// interprets \W, \n, \t, etc. as escape sequences — a path like
        /// "C:\Windows\notepad.exe" silently becomes "C:Windows\notepad.exe"
        /// and the launch fails. Forward slashes are accepted by Popen +
        /// CreateProcess on Windows and avoid the issue entirely.
        ///
        /// If the path is null/empty it is returned unchanged so callers can
        /// decide whether to emit it.
        /// </summary>
        public static string NormalizePathForRobot(string? path)
        {
            if (string.IsNullOrEmpty(path)) return path ?? "";
            return path.Replace('\\', '/');
        }
    }
}
